/**
 * 产品控制台本地服务：编排 proctor / 读 product-eval 产物。
 * 仅绑定 127.0.0.1。
 */
import { spawn } from 'node:child_process';
import {
  createReadStream,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  statSync,
