}

.dash-stat .v.err {
  color: var(--err);
}

.dash-note {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.dash-matrix {
  display: grid;
  gap: 0.4rem;
}

.dash-row {
  display: grid;
  grid-template-columns: minmax(7rem, 1.2fr) 1fr 1fr;
  gap: 0.4rem;
  align-items: stretch;
}

.dash-cell {
  padding: 0.45rem 0.55rem;
  border-radius: 6px;
  border: 1px solid var(--line);
  font-size: 0.8rem;
