}

.dash-cell.skip {
  opacity: 0.72;
  border-style: dashed;
}

.dash-cell .sub {
  display: block;
  color: var(--muted);
  font-size: 0.72rem;
  margin-top: 0.15rem;
}

.run-actions {
  flex-wrap: wrap;
  margin: 0.5rem 0 0.75rem;
