.run-actions .inline {
  display: grid;
  gap: 0.2rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.run-actions input[type='text'],
.run-actions select {
  min-width: 9rem;
  padding: 0.35rem 0.45rem;
  border-radius: 6px;
