  padding: 0.65rem 0.75rem;
  border-radius: 6px;
  border: 1px solid var(--line);
  background: #0c1016;
  font-family: var(--mono);
  font-size: 0.8rem;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--ink);
}

.fail-row {
