.wizard input[type='text'] {
  width: 100%;
  margin-top: 0.25rem;
  padding: 0.45rem 0.55rem;
  border-radius: 6px;
  border: 1px solid var(--line);
  background: #0c1016;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.85rem;
}

.bank-empty {
  color: var(--muted);
  padding: 1.5rem 0.5rem;
  border: 1px dashed var(--line);
  border-radius: 8px;
  text-align: center;
}

.bank-summary {
  margin: 0.35rem 0 0.5rem;
  font-size: 1.05rem;
  font-weight: 650;
}

.bank-summary.ok {
  color: var(--ok);
}

.bank-summary.err {
  color: var(--err);
}

.hint.tiny {
  font-size: 0.8rem;
  margin: 0;
}

.bank-advanced {
  margin-top: 0.5rem;
  border-top: 1px solid var(--line);
  padding-top: 0.5rem;
}

.bank-advanced summary {
  cursor: pointer;
  color: var(--muted);
  font-size: 0.85rem;
}

.run-list button.warn {
  color: var(--err);
}

.run-list button.selected {
  border-color: var(--accent);
}

button.danger {
  color: var(--err);
  border-color: var(--err);
  background: transparent;
}

.wizard {
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  color: var(--ink);
  padding: 1.25rem 1.4rem;
  max-width: min(560px, 94vw);
  width: 100%;
}

.wizard::backdrop {
  background: rgb(0 0 0 / 55%);
}

.wizard h2 {
  margin: 0 0 0.35rem;
  color: var(--ink);
  font-size: 1.1rem;
}

.wizard-preview {
  max-height: 180px;
}

.wizard-actions {
  margin-top: 1rem;
  flex-wrap: wrap;
}

.env-cols {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.env-cols .actions {
  align-items: center;
}

@media (max-width: 900px) {
  .bank-layout {
    grid-template-columns: 1fr;
  }

  .env-cols {
    grid-template-columns: 1fr;
  }
}

code {
