.dash {
  display: grid;
  gap: 0.75rem;
  margin: 0 0 1rem;
}

.dash-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.dash-pill {
  font-size: 0.78rem;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--muted);
