  border: 1px solid var(--line);
  background: #0c1016;
}

.dash-stat .k {
  display: block;
  font-size: 0.75rem;
  color: var(--muted);
}

.dash-stat .v {
  display: block;
  font-size: 1.25rem;
  font-weight: 700;
