}

.dash-stat .v.ok {
  color: var(--ok);
}

.dash-stat .v.err {
  color: var(--err);
}

.dash-note {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.dash-matrix {
  display: grid;
  gap: 0.4rem;
}

.dash-row {
