.run-actions input[type='text'],
.run-actions select {
  min-width: 9rem;
  padding: 0.35rem 0.45rem;
  border-radius: 6px;
  border: 1px solid var(--line);
  background: #0c1016;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.82rem;
}

.summary-block {
  margin: 0 0 0.75rem;
  padding: 0.65rem 0.75rem;
  border-radius: 6px;
  border: 1px solid var(--line);
  background: #0c1016;
  font-family: var(--mono);
  font-size: 0.8rem;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--ink);
