.fail-row {
  display: grid;
  gap: 0.35rem;
  margin-bottom: 0.65rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--line);
}

.fail-row:last-child {
  border-bottom: 0;
  margin-bottom: 0;
}

.bank-intro {
  margin: 0 0 1rem;
  color: var(--muted);
  font-size: 0.92rem;
}

.bank-intro p {
  margin: 0.2rem 0;
}

.bank-layout {
  display: grid;
  grid-template-columns: minmax(180px, 0.9fr) 1.4fr;
  gap: 1rem;
  margin-top: 0.75rem;
