.bank-edit {
  display: grid;
  gap: 0.65rem;
}

.bank-edit textarea,
.bank-edit input[type='text'],
.wizard textarea,
.wizard input[type='text'] {
  width: 100%;
  margin-top: 0.25rem;
  padding: 0.45rem 0.55rem;
  border-radius: 6px;
  border: 1px solid var(--line);
  background: #0c1016;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.85rem;
